@media screen and (prefers-reduced-motion: no-preference) {
    #page-title, #breadcrumbs, #page-content > * {
      animation-name: fadeIn;
      animation-duration: 5.50s;
      animation-iteration-count: 1;
      animation-timing-function: ease-out;
      animation-fill-mode: backwards;
    }
  }
@keyframes fadeIn {
    from {
      opacity: 0;
      transform: translate(0,30px);
    }
    to {
      opacity: 1;
      transform: translate(0,0);
    }
  }
}
.page-rate-widget-box .ratedown { display: none!important }
.page-rate-widget-box .rate-points:before, .page-rate-widget-box .rate-points span {
   content: "该层级生存难度：";
   font-size: 15px;
   letter-spacing: 0;
   color: rgb(var(--black-monochrome));
}
.page-rate-widget-box .rate-points:after, .page-rate-widget-box .rate-points span {
   content: "级 ";
   font-size: 15px;
   letter-spacing: 0;
   color: rgb(var(--black-monochrome));
}
.page-rate-widget-box span.rate-points {
   letter-spacing: -12px;
   color: transparent !important;
}
[[/module]]

